-- Viewmodel-recoil comparison variant of cw_anomaly_sig220. Generated by work/build_vm_recoil.py.
-- Bolt motion measured from the viewmodel: "slide" in anm_shots, 1.797 units, peak frame 1, home frame 3 at 30 fps.

AddCSLuaFile()

SWEP.Base = "cw_anomaly_sig220"

SWEP.PrintName = "SIG P220 (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

if CLIENT then
	SWEP.BoltBone = "slide"
	SWEP.BoltShootOffset = Vector(0, 0, 1.797)
	SWEP.BoltBonePositionRecoverySpeed = 27
	SWEP.HoldBoltWhileEmpty = true
	SWEP.DontHoldWhenReloading = true

	killicon.Add("cw_anomaly_sig220_vmrecoil", "vgui/killicons/tfa_anomaly_sig220", Color(255, 255, 255))
end

